"""
Load fixtures generated by an old spikeinterface release with the current code and check
they reload correctly.

This test is workflow-only: it lives outside src/ so the normal test suite does not
collect it, and cross_version_serialization.yml invokes it by path after generating the
fixtures (pointed to by SI_SERIALIZATION_FIXTURES_DIR). Because it sits next to objects.py,
it imports the shared objects directly.
"""

import os
import json
from pathlib import Path

import pytest
import numcodecs.pickles

from spikeinterface.core import load

from objects import OBJECTS, FIXTURE_SUFFIX

FIXTURES_DIR = Path(os.environ.get("SI_SERIALIZATION_FIXTURES_DIR", "serialization_fixtures"))

_CASES = [(entry, fmt) for entry in OBJECTS for fmt in entry["formats"]]


@pytest.mark.parametrize("entry,fmt", _CASES, ids=[f"{entry['id']}-{fmt}" for entry, fmt in _CASES])
def test_load_old_serialized_object(entry, fmt, monkeypatch):
    fixture = FIXTURES_DIR / f"{entry['id']}{FIXTURE_SUFFIX[fmt]}"
    assert fixture.exists(), f"missing fixture {fixture}"
    # Legacy Zarr fixtures contain pickled objects generated locally by this CI job.
    # Limit the opt-in to this test and support older Numcodecs without this flag.
    monkeypatch.setattr(numcodecs.pickles, "ALLOW_UNSAFE_PICKLE_DECODE", True, raising=False)
    obj = load(fixture)
    check_extra_data = None
    if (FIXTURES_DIR / f"{entry['id']}.json").exists():
        with open(FIXTURES_DIR / f"{entry['id']}.json", "r") as f:
            check_extra_data = json.load(f)
    entry["check"](obj, check_extra_data=check_extra_data)
